<template><section class="catalog"><h1>{{ overseas ? '出海渠道精选' : '国内渠道精选' }}</h1><p>仅展示平台已发布的运营精选，不代表官方排名或实时热度。</p><el-tabs v-model="channel" @tab-change="load"><el-tab-pane v-for="item in channels" :key="item.value" :label="item.label" :name="item.value" /></el-tabs><el-skeleton v-if="loading" :rows="4" animated /><el-empty v-else-if="!batches.length" description="这个渠道还没有精选批次，请平台运营收录。" /><div v-else v-for="batch in batches" :key="batch.batchId" class="batch"><div>发布于 {{ batch.publishedAt }}</div><p v-if="batch.opsNote">{{ batch.opsNote }}</p><el-card v-for="entry in batch.entries" :key="entry.entryId" shadow="never"><b>精选条目</b><p>{{ entry.recommendText || '暂无推荐说明' }}</p><small>{{ entry.reason || '暂无入选理由' }}</small></el-card></div></section></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import {useRoute} from 'vue-router';import {getPublishedCatalog,type PublishedBatch} from '@/api/marketing/catalog';defineOptions({name:'TenantCatalog'});const route=useRoute();const overseas=computed(()=>route.name==='TenantOverseas');const channels=computed(()=>overseas.value?[{label:'LinkedIn',value:'linkedin'},{label:'YouTube',value:'youtube'},{label:'Facebook',value:'facebook'}]:[{label:'公众号',value:'wechat'},{label:'小红书',value:'xiaohongshu'},{label:'抖音',value:'douyin'},{label:'哔哩哔哩',value:'bilibili'}]);const channel=ref('wechat');const loading=ref(false);const batches=ref<PublishedBatch[]>([]);const load=async()=>{loading.value=true;try{batches.value=await getPublishedCatalog(overseas.value?'overseas':'domestic',channel.value)}finally{loading.value=false}};onMounted(()=>{channel.value=channels.value[0].value;load()})</script>
<style scoped>.catalog{max-width:980px;padding:8px}.catalog h1{margin:0 0 8px}.catalog>p,small{color:#6b7280}.batch{margin:20px 0}.batch .el-card{margin-top:8px}</style>